package com.letschatafrica.chatbubble;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.util.Base64;

/**
 * The three little pictures of the neon message card (see MessagePopup): the boy, the Letschat Africa logo and the girl.
 * They are small WebP pictures kept inside the code as text, so no extra picture files are needed in the Android project.
 * A picture that cannot be decoded is simply left out of the card.
 */
final class PopupArt {

    private PopupArt() {}

    private static Bitmap boy;
    private static Bitmap logo;
    private static Bitmap girl;

    private static Bitmap decode(String b64) {
        try {
            byte[] d = Base64.decode(b64, Base64.DEFAULT);
            return BitmapFactory.decodeByteArray(d, 0, d.length);
        } catch (Throwable t) {
            return null;
        }
    }

    static synchronized Bitmap boy() {
        if (boy == null) boy = decode(BOY);
        return boy;
    }

    static synchronized Bitmap logo() {
        if (logo == null) logo = decode(LOGO);
        return logo;
    }

    static synchronized Bitmap girl() {
        if (girl == null) girl = decode(GIRL);
        return girl;
    }

    private static final String BOY =
        "";

    private static final String LOGO =
        "";

    private static final String GIRL =
        "";
}
